class DynamicArray {
    int* data;
    int capacity;
    int length;
public:
    DynamicArray(int cap = 2) : capacity(cap), length(0) { data = new int[capacity]; }
    ~DynamicArray() { delete[] data; }
    void push_back(int n) {
        if (length == capacity) resize();
        data[length++] = n;
    }
    int pop_back() { return data[--length]; }
    int get(int i) const { return data[i]; }
    void set(int i, int n) { data[i] = n; }
    int size() const { return length; }
    int get_capacity() const { return capacity; }
};
