class LinkedList {
    ListNode* head;
    int size;
public:
    LinkedList() : head(nullptr), size(0) {}
    ~LinkedList() {
        while (head) { ListNode* t = head; head = head->next; delete t; }
    }
    int get(int i) const {
        if (i < 0 || i >= size) return -1;
        ListNode* c = head;
        for (int k = 0; k < i; ++k) c = c->next;
        return c->val;
    }
    void insertHead(int v) { ListNode* n = new ListNode(v); n->next = head; head = n; size++; }
    void insertTail(int v) { /* traverse and link */ size++; }
    bool remove(int i) { /* unlink and delete */ size--; return true; }
    std::vector<int> getValues() const { /* collect into vector */ }
};
